  ('a_fb1fab5c0a30f0a89a7cd5fad873c6f0.png', 'decoration', 'Starlight Whales', 'Insomnia', 'https://cdn.discordapp.com/avatar-decoration-presets/a_fb1fab5c0a30f0a89a7cd5fad873c6f0.png', 'a_fb1fab5c0a30f0a89a7cd5fad873c6f0', 'Two glowing celestial whales playfully swim in a circle around your avatar, leaving trails of sparkling particles behind them.', 4100, '{"sku_id": "1343751620965564426", "file": "Starlight_Whales.png"}'::jsonb, 286),
  ('a_6d99f670de3fcee669660fe262e896ea.png', 'decoration', 'Mirage', 'Insomnia', 'https://cdn.discordapp.com/avatar-decoration-presets/a_6d99f670de3fcee669660fe262e896ea.png', 'a_6d99f670de3fcee669660fe262e896ea', 'Pink ethereal streaks and rings of light flow around your avatar like an aurora, emitting trails of shimmering particles.', 4100, '{"sku_id": "1343751617328975954", "file": "Mirage.png"}'::jsonb, 287),
  ('a_462b0bddc07dd495765fe12abe8b077f.png', 'decoration', 'Lava Blobs', 'Insomnia', 'https://cdn.discordapp.com/avatar-decoration-presets/a_462b0bddc07dd495765fe12abe8b077f.png', 'a_462b0bddc07dd495765fe12abe8b077f', 'Glowing, metallic liquid-like blobs drift around your avatar, mimicking the mesmerizing flow of a lava lamp.', 4100, '{"sku_id": "1343751617379307653", "file": "Lava_Blobs.png"}'::jsonb, 288),
  ('a_c9761eb6d77eef5d4f10deb6ab4a3d87.png', 'decoration', 'Luminescent Lotus', 'Insomnia', 'https://cdn.discordapp.com/avatar-decoration-presets/a_c9761eb6d77eef5d4f10deb6ab4a3d87.png', 'a_c9761eb6d77eef5d4f10deb6ab4a3d87', 'Eight glowing flowers with purple petals and blue centers frame your avatar. The petals bloom and close, one after the other, in a mesmerizing rhythmic sequence.', 4100, '{"sku_id": "1343751621146054727", "file": "Luminescent_Lotus.png"}'::jsonb, 289),
  ('a_c150c7d7331442961a42d4d580860525.png', 'decoration', 'Woolgathering', 'Insomnia', 'https://cdn.discordapp.com/avatar-decoration-presets/a_c150c7d7331442961a42d4d580860525.png', 'a_c150c7d7331442961a42d4d580860525', 'Colorful glowing animals, including a frog, sheep, squirrel, and cat, form a whimsical ring around your avatar, as if in a magical trance.', 4100, '{"sku_id": "1343751621175148645", "file": "Woolgathering.png"}'::jsonb, 290),
  ('a_3c97a2d37f433a7913a1c7b7a735d000.png', 'decoration', 'Angry', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_3c97a2d37f433a7913a1c7b7a735d000.png', 'a_3c97a2d37f433a7913a1c7b7a735d000', 'Anger Symbol with Exclamation Mark Speech Bubble, Anime-Style, Red, Animated', 4100, '{"sku_id": "1144308439720394944", "file": "Angry.png"}'::jsonb, 291),
  ('a_45f7f9975255971b197d34d77fb50ede.png', 'decoration', 'Magical Girl', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_45f7f9975255971b197d34d77fb50ede.png', 'a_45f7f9975255971b197d34d77fb50ede', 'Magical purple energy encircles your avatar, with sparkling pink stars and hearts swirling around in a cyclone-like dance.', 4100, '{"sku_id": "1341506444188450816", "file": "Magical_Girl.png"}'::jsonb, 292),
  ('a_3e1fc3c7ee2e34e8176f4737427e8f4f.png', 'decoration', 'Heartbloom', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_3e1fc3c7ee2e34e8176f4737427e8f4f.png', 'a_3e1fc3c7ee2e34e8176f4737427e8f4f', 'Hearts and flowers decorate the avatar''s frame for a lovely, charming vibe.', 4100, '{"sku_id": "1212570343567261736", "file": "Heartbloom.png"}'::jsonb, 293),
  ('a_df5442048d7d5b8b8906f3a9cd93f0ab.png', 'decoration', 'Rumbling', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_df5442048d7d5b8b8906f3a9cd93f0ab.png', 'a_df5442048d7d5b8b8906f3a9cd93f0ab', 'Bold ''zuzun'' characters and dynamic, wavy lines creating a vibrant rumbling effect around your avatar.', 4100, '{"sku_id": "1341506444150702080", "file": "Rumbling.png"}'::jsonb, 294),
  ('a_e0a2df84cf7eb8e098a13e37ec9027c1.png', 'decoration', 'Sakura Scholar', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_e0a2df84cf7eb8e098a13e37ec9027c1.png', 'a_e0a2df84cf7eb8e098a13e37ec9027c1', 'Your avatar dons a cute and classic Japanese school uniform with a green collar and red tie. Pink sakura blossoms crown your head for a dreamy look.', 4100, '{"sku_id": "1341506444209422336", "file": "Sakura_Scholar.png"}'::jsonb, 295),
  ('a_44045ae47175eaca4ed1b4d889b62b27.png', 'decoration', 'Sushi Roll', 'Anime', 'https://cdn.discordapp.com/avatar-decoration-presets/a_44045ae47175eaca4ed1b4d889b62b27.png', 'a_44045ae47175eaca4ed1b4d889b62b27', 'You find yourself enveloped in fluffy white rice, with a gorgeous slab of orange sashimi perched atop your head. It appears you are a sushi roll.', 4100, '{"sku_id": "1341506444230393856", "file": "Sushi_Roll.png"}'::jsonb, 296),
  ('a_7fecc9d20cbbf54644c9a532f7db4664.png', 'decoration', 'Ring of Roses', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_7fecc9d20cbbf54644c9a532f7db4664.png', 'a_7fecc9d20cbbf54644c9a532f7db4664', 'Pink and red roses frame your avatar, occasionally shedding petals that gently flutter like Valentine confetti.', 4100, '{"sku_id": "1333866045324394547", "file": "Ring_of_Roses.png"}'::jsonb, 297),
  ('a_06cb5a74ff1bf68e72c013d31270ed7b.png', 'decoration', 'Ring of Roses (Blue)', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_06cb5a74ff1bf68e72c013d31270ed7b.png', 'a_06cb5a74ff1bf68e72c013d31270ed7b', 'Blue roses frame your avatar, occasionally shedding petals that gently flutter like confetti.', 4100, '{"sku_id": "1333866045345366136", "file": "Ring_of_Roses_(Blue).png"}'::jsonb, 298),
  ('a_63a69109db554a66764cbe61c6e556ef.png', 'decoration', 'Heartstrings', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_63a69109db554a66764cbe61c6e556ef.png', 'a_63a69109db554a66764cbe61c6e556ef', 'Heart-shaped string lights wrap your avatar in the shape of a heart, each bulb shining in turn, creating a fun light show of pink and red.', 4100, '{"sku_id": "1333866045370531921", "file": "Heartstrings.png"}'::jsonb, 299),
  ('a_42cc3fe7133523096466102e7a222003.png', 'decoration', 'Heartstrings (Blue)', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_42cc3fe7133523096466102e7a222003.png', 'a_42cc3fe7133523096466102e7a222003', 'Heart-shaped string lights wrap your avatar in the shape of a heart, each bulb shining in turn, creating a fun blue light show.', 4100, '{"sku_id": "1333866045391503463", "file": "Heartstrings_(Blue).png"}'::jsonb, 300),
  ('a_c86b11a49bb8057ce9c974a6f7ad658a.png', 'decoration', 'Angel', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_c86b11a49bb8057ce9c974a6f7ad658a.png', 'a_c86b11a49bb8057ce9c974a6f7ad658a', 'Your avatar is dressed as an angel with fluffy angel wings and a glowing halo. Every flutter of your wings releases sparkles and little hearts.', 4100, '{"sku_id": "1333866045236314327", "file": "Angel.png"}'::jsonb, 301),
  ('a_b4dcf63b6af2e20cba91af61c0e3a8a7.png', 'decoration', 'Devil', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_b4dcf63b6af2e20cba91af61c0e3a8a7.png', 'a_b4dcf63b6af2e20cba91af61c0e3a8a7', 'Your avatar is dressed as a mischievous red devil with devilish wings, horns, and a heart-tipped tail. Every flutter of your wings releases hearts ignited in blue flames.', 4100, '{"sku_id": "1333866045261480007", "file": "Devil.png"}'::jsonb, 302),
  ('a_e60cc4d7f4d8a6e79dd8cc67d2b13d6c.png', 'decoration', 'Aim for Love', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_e60cc4d7f4d8a6e79dd8cc67d2b13d6c.png', 'a_e60cc4d7f4d8a6e79dd8cc67d2b13d6c', 'A cute pink bunny with tiny angel wings draws its bow and fires a heart-tipped arrow into the distance. You can''t help but wonder where the arrow is headed...', 4100, '{"sku_id": "1333866045282451527", "file": "Aim_for_Love.png"}'::jsonb, 303),
  ('a_7f44d538ec830f479605f7bf8720afda.png', 'decoration', 'Lovestruck', 'Valentines', 'https://cdn.discordapp.com/avatar-decoration-presets/a_7f44d538ec830f479605f7bf8720afda.png', 'a_7f44d538ec830f479605f7bf8720afda', 'A pink heart bubble engulfs your avatar. Suddenly, a heart-tipped arrow from out of nowhere pops the bubble, releasing a flurry of heart bubbles. You can''t help but wonder who fired the arrow...', 4100, '{"sku_id": "1333866045303423026", "file": "Lovestruck.png"}'::jsonb, 304),
  ('a_ccee9031d66bc0f2d7ed0c6178d01784.png', 'decoration', 'Golden Hex', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_ccee9031d66bc0f2d7ed0c6178d01784.png', 'a_ccee9031d66bc0f2d7ed0c6178d01784', 'A hex tile made of gold outlines your avatar like a glorious portrait frame.', 4100, '{"sku_id": "1333278032789635082", "file": "Golden_Hex.png"}'::jsonb, 305),
  ('a_9d95e36bc282523fddc63d31a8d01091.png', 'decoration', 'Terrain Tiles', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_9d95e36bc282523fddc63d31a8d01091.png', 'a_9d95e36bc282523fddc63d31a8d01091', 'Your avatar’s hex tile morphs through desert, lush forests, and oceanic blues - perfect for those who love to explore.', 4100, '{"sku_id": "1333278032814673940", "file": "Terrain_Tiles.png"}'::jsonb, 306),
  ('a_8dddba8c2a9704a943bb7020a3d0a418.png', 'decoration', 'Hex Tiles', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_8dddba8c2a9704a943bb7020a3d0a418.png', 'a_8dddba8c2a9704a943bb7020a3d0a418', 'Desert, forest, and sea hex tiles frame your avatar, capturing the variety and wonder of your growing civilization.', 4100, '{"sku_id": "1333278032835645450", "file": "Hex_Tiles.png"}'::jsonb, 307),
  ('a_fcb0de14da228879b455f1f1d3919749.png', 'decoration', 'Gold Laurel Wreath', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_fcb0de14da228879b455f1f1d3919749.png', 'a_fcb0de14da228879b455f1f1d3919749', 'A regal laurel wreath of gold encircles your avatar, symbolizing the grandeur of civilization''s mightiest rulers.', 4100, '{"sku_id": "1333278032768536596", "file": "Gold_Laurel_Wreath.png"}'::jsonb, 308),
  ('a_a4e8e02dbbba6889428c744df7aa5a81.png', 'decoration', 'City Walls', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_a4e8e02dbbba6889428c744df7aa5a81.png', 'a_a4e8e02dbbba6889428c744df7aa5a81', 'Fortified stone walls encircle and protect your avatar in the shape of a hex, each corner alight with torches of fire.', 4100, '{"sku_id": "1333278032852549705", "file": "City_Walls.png"}'::jsonb, 309),
  ('a_2b95e7a4951a1a092e7870bf1d456262.png', 'decoration', 'Next Turn Button', 'Civilization VII', 'https://cdn.discordapp.com/avatar-decoration-presets/a_2b95e7a4951a1a092e7870bf1d456262.png', 'a_2b95e7a4951a1a092e7870bf1d456262', 'All that stands between you and your future is this glorious, golden ''Next Turn'' button - go on, make your move.', 4100, '{"sku_id": "1333278032877715467", "file": "Next_Turn_Button.png"}'::jsonb, 310),
  ('a_d859cee893cffd5dd0fa17a6caea44e0.png', 'decoration', 'Snake''s Hug', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_d859cee893cffd5dd0fa17a6caea44e0.png', 'a_d859cee893cffd5dd0fa17a6caea44e0', 'A red snake in lunar year colors coils gracefully around your avatar for a scaly hug.', 4100, '{"sku_id": "1329609528525979658", "file": "Snake''s_Hug.png"}'::jsonb, 311),
  ('a_50b440810b1bbd89f6284f36d40ad0af.png', 'decoration', 'Koi Pond', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_50b440810b1bbd89f6284f36d40ad0af.png', 'a_50b440810b1bbd89f6284f36d40ad0af', 'Two koi fish swimming beneath the water covering the avatar surface, and dive down repeatedly as they swim in circles.', 4100, '{"sku_id": "1202074101343322184", "file": "Koi_Pond.png"}'::jsonb, 312),
  ('a_0f4f1b40921ce680b60007e94427d1f2.png', 'decoration', 'Firecrackers', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_0f4f1b40921ce680b60007e94427d1f2.png', 'a_0f4f1b40921ce680b60007e94427d1f2', 'A string of firecrackers appears to the left of the avatar, and after a moment, lights off with a flurry of sparks!', 4100, '{"sku_id": "1202073775840178206", "file": "Firecrackers.png"}'::jsonb, 313),
  ('a_1b1df0ae8c2d34afd85da5c22a0d761a.png', 'decoration', 'Lucky Envelopes', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_1b1df0ae8c2d34afd85da5c22a0d761a.png', 'a_1b1df0ae8c2d34afd85da5c22a0d761a', 'Two red envelopes sit on the left side of the avatar. One envelope moves forward and opens up to ingest a number of gold coins.', 4100, '{"sku_id": "1202445890909110323", "file": "Lucky_Envelopes.png"}'::jsonb, 314),
  ('a_2e55d644e11acb6253dfa422eff16dfd.png', 'decoration', 'Lotus Flower', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_2e55d644e11acb6253dfa422eff16dfd.png', 'a_2e55d644e11acb6253dfa422eff16dfd', 'Delicate petals of a beautiful pink lotus flower bloom around your avatar.', 4100, '{"sku_id": "1329609528546693170", "file": "Lotus_Flower.png"}'::jsonb, 315),
  ('a_9e16d86b2887eb2a3bed36a5b8876935.png', 'decoration', 'Red Lantern', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_9e16d86b2887eb2a3bed36a5b8876935.png', 'a_9e16d86b2887eb2a3bed36a5b8876935', 'An ornamental red new year lantern frames your avatar, symbolizing good luck and joy for your year ahead.', 4100, '{"sku_id": "1329609528571858975", "file": "Red_Lantern.png"}'::jsonb, 316),
  ('a_9d2ff9685be0c668ef6990b0035fac17.png', 'decoration', 'Fan Flourish', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_9d2ff9685be0c668ef6990b0035fac17.png', 'a_9d2ff9685be0c668ef6990b0035fac17', 'A fan sits to the left of the avatar with plum blossoms. The fan expands for a moment, shielding the avatar from your gaze, before closing with an acrobatic movement.', 4100, '{"sku_id": "1202070083816661043", "file": "Fan_Flourish.png"}'::jsonb, 317),
  ('a_63b29ec5b1ea6bb01c2251049838d822.png', 'decoration', 'Lunar Lanterns', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_63b29ec5b1ea6bb01c2251049838d822.png', 'a_63b29ec5b1ea6bb01c2251049838d822', 'From on top of the avatar, a tiled roof sits with lanterns swinging back and forth in the breeze.', 4100, '{"sku_id": "1202073882111266846", "file": "Lunar_Lanterns.png"}'::jsonb, 318),
  ('a_445566ed965b2c1632a5b45c92f32d11.png', 'decoration', 'Dragon''s Smile', 'Lunar New Year', 'https://cdn.discordapp.com/avatar-decoration-presets/a_445566ed965b2c1632a5b45c92f32d11.png', 'a_445566ed965b2c1632a5b45c92f32d11', 'A dragon''s mouth perches precariously around the avatar. In a swift movement, the dragon chomps down, smiling and revealing its face.', 4100, '{"sku_id": "1202073975178665984", "file": "Dragon''s_Smile.png"}'::jsonb, 319),
  ('a_1acbe609daec21fa5b866df9e5a42cb7.png', 'decoration', 'Steampunk Cat Ears', 'Steampunk', 'https://cdn.discordapp.com/avatar-decoration-presets/a_1acbe609daec21fa5b866df9e5a42cb7.png', 'a_1acbe609daec21fa5b866df9e5a42cb7', 'Your avatar wears a stylish pair of cat ears and goggles with glass lenses. The ears and lenses flick and twitch mechanically, as if scanning your surroundings.', 4100, '{"sku_id": "1326333074040164472", "file": "Steampunk_Cat_Ears.png"}'::jsonb, 320),
  ('a_459cf2afde41f01559a4a4204ab81767.png', 'decoration', 'Mech Flora', 'Steampunk', 'https://cdn.discordapp.com/avatar-decoration-presets/a_459cf2afde41f01559a4a4204ab81767.png', 'a_459cf2afde41f01559a4a4204ab81767', 'Mechanical blossoms with blue-and-white petals swivel and unfold, releasing gentle puffs of steam each time they bloom.', 4100, '{"sku_id": "1326333074061135992", "file": "Mech_Flora.png"}'::jsonb, 321),
  ('a_a67833d0f3138d7dcdee98c39eae33d7.png', 'decoration', 'Bowler Hat', 'Steampunk', 'https://cdn.discordapp.com/avatar-decoration-presets/a_a67833d0f3138d7dcdee98c39eae33d7.png', 'a_a67833d0f3138d7dcdee98c39eae33d7', 'A fashionable purple bowler hat with mechanical gears and eyes sprouts four spider-like legs, then runs a jaunty lap around your avatar before perching again.', 4100, '{"sku_id": "1326333074082107483", "file": "Bowler_Hat.png"}'::jsonb, 322),
  ('a_bfaeda83edb41e78250eedc71bed31fc.png', 'decoration', 'Brass Beats', 'Steampunk', 'https://cdn.discordapp.com/avatar-decoration-presets/a_bfaeda83edb41e78250eedc71bed31fc.png', 'a_bfaeda83edb41e78250eedc71bed31fc', 'Antique headphones constructed from golden-copper clockwork gears and tubes plays music, emitting wispy puffs of steam from its earmuffs in tune with the beat.', 4100, '{"sku_id": "1326333074103078973", "file": "Brass_Beats.png"}'::jsonb, 323),
  ('a_f1c60c026aa89971e360ba88643d92c0.png', 'decoration', 'Timekeeper''s Clock', 'Steampunk', 'https://cdn.discordapp.com/avatar-decoration-presets/a_f1c60c026aa89971e360ba88643d92c0.png', 'a_f1c60c026aa89971e360ba88643d92c0', 'An antique, computer-like clock said to be capable of time travel encircles the avatar, complete with a vintage keyboard and a neon-green digital display.', 4100, '{"sku_id": "1326333074132176916", "file": "Timekeeper''s_Clock.png"}'::jsonb, 324),
