  ('a_09bb4197c743ea31b7eb052eddd3e892.png', 'decoration', 'Hex Lights', 'Kawaii Mode', 'https://cdn.discordapp.com/avatar-decoration-presets/a_09bb4197c743ea31b7eb052eddd3e892.png', 'a_09bb4197c743ea31b7eb052eddd3e892', 'Hexagon-shaped lights in red, green, blue, and white colors decorate the outer frame of the avatar, creating a sleek, high-tech gaming look.', 4100, '{"sku_id": "1306330663116472371", "file": "Hex_Lights.png"}'::jsonb, 360),
  ('a_af5ee420e5f860ff2cdbb5fa4633f2cf.png', 'decoration', 'The Anomaly', 'Arcane', 'https://cdn.discordapp.com/avatar-decoration-presets/a_af5ee420e5f860ff2cdbb5fa4633f2cf.png', 'a_af5ee420e5f860ff2cdbb5fa4633f2cf', 'The mysterious Anomaly has taken over your avatar, its weblike surface stretching and wrapping around it endlessly.', 4100, '{"sku_id": "1306752744258011166", "file": "The_Anomaly.png"}'::jsonb, 361),
