  ('a_9bc421cef4bdcfffeb2344b44ad91b44.png', 'decoration', 'The Monster You Created', 'Arcane', 'https://cdn.discordapp.com/avatar-decoration-presets/a_9bc421cef4bdcfffeb2344b44ad91b44.png', 'a_9bc421cef4bdcfffeb2344b44ad91b44', 'The avatar dons Jinx''s signature hairstyle. Flashing grafiti create the illusion as if Jinx was making mischievous faces over your likeness.', 4100, '{"sku_id": "1303490165074825296", "file": "The_Monster_You_Created.png"}'::jsonb, 363),
  ('a_cc1aab519baf2ab8cfa0151bed5263df.png', 'decoration', 'The Atlas Gauntlets', 'Arcane', 'https://cdn.discordapp.com/avatar-decoration-presets/a_cc1aab519baf2ab8cfa0151bed5263df.png', 'a_cc1aab519baf2ab8cfa0151bed5263df', 'Vi''s gauntlets flex their fingers before charging up and throwing out a punch with tremendous force.', 4100, '{"sku_id": "1303490165099991143", "file": "The_Atlas_Gauntlets.png"}'::jsonb, 364),
  ('a_8396e9830e3e288cd3aaa6daf18b605a.png', 'decoration', 'Flame Chompers', 'Arcane', 'https://cdn.discordapp.com/avatar-decoration-presets/a_8396e9830e3e288cd3aaa6daf18b605a.png', 'a_8396e9830e3e288cd3aaa6daf18b605a', 'Three of Jinx''s flame chompers jitter with anticipation around the avatar, ready to snap and blast anyone who dares to step close by.', 4100, '{"sku_id": "1303490165120962651", "file": "Flame_Chompers.png"}'::jsonb, 365),
