  ('a_dbb1abd90367c1a31a94f7e162f3a3c3.png', 'decoration', 'The Hexcore', 'Arcane', 'https://cdn.discordapp.com/avatar-decoration-presets/a_dbb1abd90367c1a31a94f7e162f3a3c3.png', 'a_dbb1abd90367c1a31a94f7e162f3a3c3', 'The avatar finds itself encased inside the Hexcore, its runic fragments twisting and swirling about, crackling with hextech energy.', 4100, '{"sku_id": "1303490165171294268", "file": "The_Hexcore.png"}'::jsonb, 367),
