  ('a_0e839cd79500e7b68e2bbbed54790c28.png', 'decoration', 'Phoenix', 'Mythical Creatures', 'https://cdn.discordapp.com/avatar-decoration-presets/a_0e839cd79500e7b68e2bbbed54790c28.png', 'a_0e839cd79500e7b68e2bbbed54790c28', 'Fiery phoenix wings conjoin at the bottom of the avatar. Bursts of flame surge across the wings as they gently ruffle around.', 4100, '{"sku_id": "1298033986622328842", "file": "Phoenix.png"}'::jsonb, 373),
