  ('a_66f69effef43b4f7c4f5d0739079a947.png', 'decoration', 'M. Bison', 'Street Fighter 6', 'https://cdn.discordapp.com/avatar-decoration-presets/a_66f69effef43b4f7c4f5d0739079a947.png', 'a_66f69effef43b4f7c4f5d0739079a947', 'The avatar dons M. Bison''s signature cap while summoning menacing purple energy orbs that radiate dark power from each of his hands.', 4100, '{"sku_id": "1285465421214126100", "file": "M._Bison.png"}'::jsonb, 377),
  ('a_bba133b88b21e1b4a36637335536c3a8.png', 'decoration', 'Chun-Li', 'Street Fighter 6', 'https://cdn.discordapp.com/avatar-decoration-presets/a_bba133b88b21e1b4a36637335536c3a8.png', 'a_bba133b88b21e1b4a36637335536c3a8', 'The avatar dons Chun-Li''s signature odango buns, as a whirlwind of strikes leaves behind a dazzling trail of blue streaks.', 4100, '{"sku_id": "1285465421050548345", "file": "Chun-Li.png"}'::jsonb, 378),
  ('a_f524554b7f42a214d15c226c344a5357.png', 'decoration', 'Ken', 'Street Fighter 6', 'https://cdn.discordapp.com/avatar-decoration-presets/a_f524554b7f42a214d15c226c344a5357.png', 'a_f524554b7f42a214d15c226c344a5357', 'Ken''s wild blond hair and curled hands decorate the avatar. The hands begin to motion and carry out Ken''s legendary Shoryuken uppercut move.', 4100, '{"sku_id": "1285465421071519825", "file": "Ken.png"}'::jsonb, 379),
