  ('a_eb003dc2b5c6d85c8e18cc9336fcdad3.png', 'decoration', 'Chrysanthemums', 'Autumn Equinox', 'https://cdn.discordapp.com/avatar-decoration-presets/a_eb003dc2b5c6d85c8e18cc9336fcdad3.png', 'a_eb003dc2b5c6d85c8e18cc9336fcdad3', 'The avatar is decorated with sprouted and blooming chrysanthemums that continuously change from pink to blue as a pair of glowing butterflies - one blue and the other pink as well - encircle the avatar.', 4100, '{"sku_id": "1282816431850782730", "file": "Chrysanthemums.png"}'::jsonb, 383),
